package handler
import("encoding/json";"net/http";"strings";"time")
type policyRequest struct{ID string `json:"id"`;Capacity *float64 `json:"capacity"`;RefillPerSec *float64 `json:"refillPerSec"`;CostPerReq *float64 `json:"costPerReq"`;ClientKey string `json:"clientKey"`;Reset bool `json:"reset"`}
func policiesHandler(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json");w.Header().Set("Cache-Control","no-store");switch r.Method{case http.MethodGet:appStore.mu.Lock();now:=time.Now();for id,p:=range appStore.policies{for k,b:=range appStore.buckets{if strings.HasPrefix(k,id+"::"){refill(b,p,now)}}};out:=[]PolicyView{};for _,p:=range appStore.policies{out=append(out,PolicyView{p,appStore.viewsLocked(p)})};appStore.mu.Unlock();json.NewEncoder(w).Encode(map[string]any{"policies":out})
case http.MethodPost:var q policyRequest;if json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20)).Decode(&q)!=nil{http.Error(w,`{"error":"invalid JSON"}`,400);return};appStore.mu.Lock();p,ok:=appStore.policies[q.ID];if !ok{appStore.mu.Unlock();http.Error(w,`{"error":"unknown policy"}`,404);return};if q.Capacity!=nil{if *q.Capacity<1||*q.Capacity>100000{appStore.mu.Unlock();http.Error(w,`{"error":"invalid capacity"}`,400);return};p.Capacity=*q.Capacity};if q.RefillPerSec!=nil{if *q.RefillPerSec<0||*q.RefillPerSec>100000{appStore.mu.Unlock();http.Error(w,`{"error":"invalid refill rate"}`,400);return};p.RefillPerSec=*q.RefillPerSec};if q.CostPerReq!=nil{if *q.CostPerReq<=0||*q.CostPerReq>p.Capacity{appStore.mu.Unlock();http.Error(w,`{"error":"invalid request cost"}`,400);return};p.CostPerReq=*q.CostPerReq};appStore.policies[p.ID]=p;if q.Reset{if q.ClientKey!=""{delete(appStore.buckets,bucketID(p.ID,q.ClientKey))}else{for k:=range appStore.buckets{if strings.HasPrefix(k,p.ID+"::"){delete(appStore.buckets,k)}}}};v:=PolicyView{p,appStore.viewsLocked(p)};appStore.mu.Unlock();json.NewEncoder(w).Encode(map[string]any{"policy":v,"message":"Policy updated"})
default:w.Header().Set("Allow","GET, POST");http.Error(w,`{"error":"method not allowed"}`,405)}}
